<?php

namespace Database\Seeders;

use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;

class H5PAddDictationOneThreeSeeder extends Seeder
{
    public function run()
    {
        $params = ['name' => "H5P.Dictation", "major_version" => 1, "minor_version" => 3];
        $lib = DB::table('h5p_libraries')->where($params)->first();

        if (empty($lib)) {
            $libId = DB::table('h5p_libraries')->insertGetId([
                'name' => 'H5P.Dictation',
                'title' => 'Dictation',
                'major_version' => 1,
                'minor_version' => 3,
                'patch_version' => 3,
                'embed_types' => 'iframe',
                'runnable' => 1,
                'restricted' => 0,
                'fullscreen' => 0,
                'preloaded_js' => 'dist/h5p-dictation.js',
                'preloaded_css' => 'dist/h5p-dictation.css',
                'drop_library_css' => '',
                'semantics' => $this->getSemantics(),
                'tutorial_url' => ' ',
                'has_icon' => 1
            ]);

            $this->insertDependentLibraries($libId);
            $this->insertLibrariesLanguages($libId);

            $organizations = DB::table('organizations')->pluck('id');
            $currentDate = now();

            foreach ($organizations as $organizationId) {
                $activityTypes = DB::table('activity_types')->whereOrganizationId($organizationId)->pluck('id', 'title');
                if (!isset($activityTypes['Multimedia'])) {
                    continue;
                }
                $params2 = ['title' => 'Dictation', 'organization_id' => $organizationId];
                DB::table('activity_items')->updateOrInsert($params2, [
                    'title' => 'Dictation',
                    'image' => '',
                    'description' => 'Train listening comprehension and spelling with audio dictation exercises',
                    'activity_type_id' => $activityTypes['Multimedia'],
                    'h5pLib' => 'H5P.Dictation 1.3',
                    'demo_activity_id' => '0',
                    'demo_video_id' => '',
                    'type' => 'h5p',
                    'created_at' => $currentDate,
                    'deleted_at' => null,
                    'organization_id' => $organizationId,
                ]);
            }
        }
    }

    private function insertDependentLibraries($libId)
    {
        $h5pQuestionParams = ['name' => "H5P.Question", "major_version" => 1, "minor_version" => 5];
        $h5pQuestionLib = DB::table('h5p_libraries')->where($h5pQuestionParams)->first();
        $h5pQuestionLibId = $h5pQuestionLib->id;
        DB::table('h5p_libraries_libraries')->insert(['library_id' => $libId, 'required_library_id' => $h5pQuestionLibId, 'dependency_type' => 'preloaded']);

        $h5pJoubelUIParams = ['name' => "H5P.JoubelUI", "major_version" => 1, "minor_version" => 3];
        $h5pJoubelUILib = DB::table('h5p_libraries')->where($h5pJoubelUIParams)->first();
        $h5pJoubelUILibId = $h5pJoubelUILib->id;
        DB::table('h5p_libraries_libraries')->insert(['library_id' => $libId, 'required_library_id' => $h5pJoubelUILibId, 'dependency_type' => 'preloaded']);

        $h5pAudioParams = ['name' => "H5P.Audio", "major_version" => 1, "minor_version" => 5];
        $h5pAudioLib = DB::table('h5p_libraries')->where($h5pAudioParams)->first();
        $h5pAudioLibId = $h5pAudioLib->id;
        DB::table('h5p_libraries_libraries')->insert(['library_id' => $libId, 'required_library_id' => $h5pAudioLibId, 'dependency_type' => 'preloaded']);

        $h5pTextUtilsParams = ['name' => "H5P.TextUtilities", "major_version" => 1, "minor_version" => 3];
        $h5pTextUtilsLib = DB::table('h5p_libraries')->where($h5pTextUtilsParams)->first();
        $h5pTextUtilsLibId = $h5pTextUtilsLib->id;
        DB::table('h5p_libraries_libraries')->insert(['library_id' => $libId, 'required_library_id' => $h5pTextUtilsLibId, 'dependency_type' => 'preloaded']);

        $h5pVerticalTabsParams = ['name' => "H5PEditor.VerticalTabs", "major_version" => 1, "minor_version" => 3];
        $h5pVerticalTabsLib = DB::table('h5p_libraries')->where($h5pVerticalTabsParams)->first();
        $h5pVerticalTabsLibId = $h5pVerticalTabsLib->id;
        DB::table('h5p_libraries_libraries')->insert(['library_id' => $libId, 'required_library_id' => $h5pVerticalTabsLibId, 'dependency_type' => 'editor']);

        $h5pRangeListParams = ['name' => "H5PEditor.RangeList", "major_version" => 1, "minor_version" => 0];
        $h5pRangeListLib = DB::table('h5p_libraries')->where($h5pRangeListParams)->first();
        $h5pRangeListLibId = $h5pRangeListLib->id;
        DB::table('h5p_libraries_libraries')->insert(['library_id' => $libId, 'required_library_id' => $h5pRangeListLibId, 'dependency_type' => 'editor']);

        $h5pShowWhenParams = ['name' => "H5PEditor.ShowWhen", "major_version" => 1, "minor_version" => 0];
        $h5pShowWhenLib = DB::table('h5p_libraries')->where($h5pShowWhenParams)->first();
        $h5pShowWhenLibId = $h5pShowWhenLib->id;
        DB::table('h5p_libraries_libraries')->insert(['library_id' => $libId, 'required_library_id' => $h5pShowWhenLibId, 'dependency_type' => 'editor']);

        $h5pAudioRecorderParams = ['name' => "H5PEditor.AudioRecorder", "major_version" => 1, "minor_version" => 0];
        $h5pAudioRecorderLib = DB::table('h5p_libraries')->where($h5pAudioRecorderParams)->first();
        $h5pAudioRecorderLibId = $h5pAudioRecorderLib->id;
        DB::table('h5p_libraries_libraries')->insert(['library_id' => $libId, 'required_library_id' => $h5pAudioRecorderLibId, 'dependency_type' => 'editor']);
    }

