            'translation' => json_encode(json_decode('{"semantics":[{"label":"Στοιχεία πολυμέσων","fields":[{"label":"Τύπος","description":"Προσθήκη στοιχείου πολυμέσων προς εμφάνιση πάνω από την ερώτηση (προαιρετικό)."},{"label":"Απενεργοποίηση μεγέθυνσης εικόνας"}]},{"label":"Περιγραφή εργασίας","description":"Περιγράψτε την εργασία σας εδώ.","placeholder":"Παρακαλώ άκουσε προσεκτικά και γράψε εδώ τι ακούς."},{"label":"Προτάσεις","widgets":[{"label":"Προεπιλεγμένο"}],"entity":"Πρόταση","field":{"label":"Πρόταση","fields":[{"label":"Περιγραφή","description":"Μπορείτε προαιρετικά να προσθέσετε μια απλή περιγραφή πάνω από το πεδίο εισαγωγής κειμένου (χρησιμεύει π.χ. για τους διαλόγους)"},{"label":"Δείγμα ήχου","description":"Πρόταση που προφέρεται σε κανονική ταχύτητα"},{"label":"Δείγμα ήχου αργό","description":"Πρόταση που προφέρεται σε αργή ταχύτητα"},{"label":"Κείμενο","description":"Το κείμενο που πρέπει να γραφτεί. Μπορείτε να προσθέσετε εναλλακτικές ορθογραφίες για μία λέξη τοποθετώντας ανάμεσά τους μια κατακόρυφη γραμμή (|)."}]}},{"label":"Συνολική ανατροφοδότηση","fields":[{"widgets":[{"label":"Προεπιλογή"}],"label":"Χαρακτηρισμός κάθε κλίμακας βαθμολογίας","description":"Κάντε κλικ στο κουμπί \"Προσθήκη κλίμακας\" για να προσθέσετε όσες  κλίμακες ή διαβαθμίσεις επιθυμείτε. Παράδειγμα: 0-20% Χαμηλή βαθμολογία, 21-91% Μέτρια βαθμολογία, 91-100% Εξαιρετική βαθμολογία!","entity":"κλιμακας","field":{"fields":[{"label":"Βαθμολογία"},{"label":"Χαρακτηρισμός","placeholder":"Συμπληρώστε τον χαρακτηρισμό"}]}}]},{"label":"Ρυθμίσεις κουίζ","description":"Αυτές οι ρυθμίσεις σας επιτρέπουν να καθορίσετε τον τρόπο λειτουργίας του κουίζ.","fields":[{"label":"Μέγιστος αριθμός προσπαθειών","description":"Θα περιορίσει το πόσες φορές μπορούν να ακουστούν τα δείγματα ήχου για κάθε πρόταση."},{"label":"Μέγιστος αριθμός προσπαθειών σε χαμηλή ταχύτητα","description":"Θα περιορίσει το πόσες φορές μπορούν να ακουστούν τα δείγματα ήχου για κάθε πρόταση."},{"label":"Απενεργοποίηση της επιλογής παύσης","description":"Εάν επιλεγεί, δεν είναι δυνατή η παύση του ήχου κατά την αναπαραγωγή."},{"label":"Play button delay","description":"Optionally set a time period of up to three seconds that playing a button should be delayed. This is useful if you want to allow students to enter the text field before they start listening."},{"label":"Ανακάτεμα προτάσεων","description":"Καθορίστε πότε πρέπει να ανακατεύονται οι προτάσεις.","options":[{"label":"Ποτέ"},{"label":"Μία φορά κατά την έναρξη της άσκησης"},{"label":"Σε κάθε προσπάθεια"}]},{"label":"Βαθμολογία","fields":[{"label":"Αγνόηση σημείων στίξης","description":"Αν επιλεγεί, τα σημεία στίξης δεν θα λαμβάνονται υπόψη κατά τη βαθμολόγηση."},{"label":"Λειτουργία μηδενικών λαθών","description":"Εάν επιλεγεί, μόνο οι σωστές απαντήσεις θα ληφθούν υπόψη για τη βαθμολόγηση. Τα λάθη δεν θα τιμωρούνται."},{"label":"Τυπογραφικά λάθη","description":"Προσδιορίστε σε ποιο βαθμό τα σφάλματα πληκτρολόγησης (λέξη με 3-9 χαρακτήρες: μέχρι 1 λάθος, λέξη με περισσότερους από 9 χαρακτήρες: μέχρι 2 λάθη) θεωρούνται λάθη ορθογραφίας.","options":[{"label":"100%"},{"label":"50%"},{"label":"0%"}]}]},{"label":"Κείμενο","fields":[{"label":"Διαχωριστικό λέξεων","description":"Καθορίστε το διαχωριστικό των λέξεων διαφορετικό από τον χαρακτήρα διαστήματος για την υποστήριξη εναλλακτικών λύσεων με διαφορετικό αριθμό λέξεων."},{"label":"Κατεύθυνση γλώσσας","description":"Καθορίστε την κατεύθυνση της γλώσσας που χρησιμοποιείται (από δεξιά προς τα αριστερά ή από αριστερά προς τα δεξιά)","options":[{"label":"Αυτόματος εντοπισμός"},{"label":"Από δεξιά προς τα αριστερά"},{"label":"Από αριστερά προς τα δεξιά"}]},{"label":"Διαχωρισμός χαρακτήρων","description":"Ενεργοποιήστε τον στην περίπτωση που συγκεκριμένοι χαρακτήρες (π.χ. κινέζικοι χαρακτήρες Χαν) πρέπει να διαχωρίζονται αυτόματα σε ξεχωριστές λέξεις."}]},{"label":"Παρουσίαση ανατροφοδοτήσεων","fields":[{"label":"Ειδική προβολή τυπογραφικών λαθών","description":"Αν επιλεγεί, τα τυπογραφικά λάθη θα προβάλλονται με τρόπο που θα τα διαχωρίζει από τα λάθη ορθογραφίας."},{"label":"Παρουσίαση εναλλακτικών ορθογραφιών στη λύση","description":"Καθορίστε το πόσες από τις εναλλακτικές ορθογραφίες θα παρουσιάζονται στη λύση.","options":[{"label":"Παρουσίαση μόνο της πρώτης εναλλακτικής ορθογραφίας"},{"label":"Παρουσίαση όλων των εναλλακτικών ορθογραφιών"}]}]},{"label":"Ενεργοποίηση κουμπιού \"Επανάληψη\""},{"label":"Ενεργοποίηση κουμπιού \"Προβολή λύσης\""},{"label":"Εμφάνιση λύσης κατά τον έλεγχο"}]},{"label":"Διεπαφή χρήστη","fields":[{"label":"Συνολική ανατροφοδότηση","description":"Μπορείτε να χρησιμοποιήσετε τις εξής μεταβλητές: @matches αριθμός ταυτοποιήσεων, @total συνολικά λάθη, @capped μέγιστα συνολικά λάθη, @wrong λάθος λέξεις, @added πρόσθετες λέξεις, @missing λέξεις που λείπουν, @typo σφάλματα πληκτρολόγησης","default":"Έχεις κάνει συνολικά @total λάθη."},{"label":"Γενική ανατροφοδότηση (λειτουργία μηδενικών λαθών)","description":"Μπορείτε να χρησιμοποιήσετε διάφορες μεταβλητές που θα αντικατασταθούν με τον κατάλληλο αριθμό: @wrong = λάθος λέξεις, @added = πρόσθετες λέξεις, @missing = λέξεις που λείπουν, @typo = ορθογραφικά λάθη.","default":"Πληκτρολογήσατε σωστά @total λέξη/εις και @typo με μικρά λάθη."},{"label":"Ετικέτα κουμπιού \"Έλεγχος\"","default":"Έλεγχος"},{"label":"Ετικέτα κουμπού \"Υποβολή\"","default":"Υποβολή"},{"label":"Ετικέτα κουμπού \"Επανάληψη\"","default":"Επανάληψη"},{"label":"Ετικέτα κουμπιού \"Προβολή λύσης\"","default":"Λύση"},{"label":"Μήνυμα ήχου που δεν υποστηρίζεται","default":"Ο φυλλομετρητής σας δεν υποστηρίζει αυτόν τον τύπο ήχου."}]},{"label":"Ακουστική υποβοήθηση","fields":[{"label":"Περιγραφή υποστηρικτικής τεχνολογίας για το κουμπί \"Έλεγχος\"","default":"Ελέγξτε τις απαντήσεις. Οι απαντήσεις θα σημειωθούν ως σωστές, λανθασμένες ή μη αναπαντημένες."},{"label":"Περιγραφή υποστηρικτικής τεχνολογίας για το κουμπί \"Προβολή λύσης\"","default":"Προβολή της λύσης. Η εργασία θα επισημανθεί με τη σωστή λύση."},{"label":"Περιγραφή υποστηρικτικής τεχνολογίας για το κουμπί \"Επανάληψη\"","default":"Επαναλάβετε την εργασία. Επαναφέρετε όλες τις απαντήσεις και ξεκινήστε από την αρχή."},{"label":"Κουμπί αναπαραγωγής","default":"Αναπαραγωγή"},{"label":"Κουμπί αργής αναπαραγωγής","default":"Αργή αναπαραγωγή"},{"label":"Προσπάθειες που απομένουν (κείμενο ακουστικής υποβοήθησης)","description":"@number θα αντικατασταθεί από τον τρέχοντα αριθμό προσπαθειών που απομένουν.","default":"Προσπάθειες που απομένουν: @number"},{"label":"Άπειρο (κείμενο ακουστικής υποβοήθησης)","default":"Άπειρο"},{"label":"Πεδίο εισαγωγής κειμένου","default":"Γράψε αυτό που άκουσες"},{"label":"Τα αποτελέσματά σας","description":"@score θα αντικατασταθεί από τον αριθμό βαθμών. @total θα αντικατασταθεί απο τον μέγιστο αριθμό βαθμών.","default":"Πήρατε @score από @total βαθμούς"},{"label":"Λύση","default":"Λύση"},{"label":"Πρόταση","default":"Πρόταση"},{"label":"Αντικείμενο","default":"Αντικείμενο"},{"label":"Σωστό","default":"Σωστό"},{"label":"Λάθος","default":"Λάθος"},{"label":"Μικρής σημασίας λάθος","default":"Μικρής σημασίας λάθος"},{"label":"Λέξη ή σύμβολο που λείπει","default":"Λείπει"},{"label":"Προστέθηκε λέξη ή σύμβολο","default":"Προστέθηκε"},{"label":"Σωστή λύση","default":"Θα έπρεπε να είναι"},{"label":"Ή","default":"Ή"},{"label":"Σημείο","default":"Σημείο"},{"label":"Σημεία","default":"Σημεία"},{"label":"Τελεία","default":"Τελεία"},{"label":"Θαυμαστικό","default":"Θαυμαστικό"},{"label":"Λατινικό ερωτηματικό","default":"Λατινικό ερωτηματικό"},{"label":"Κόμμα","default":"Κόμμα"},{"label":"Μονά εισαγωγικά","default":"Μονά εισαγωγικά"},{"label":"Διπλά εισαγωγικά","default":"Διπλά εισαγωγικά"},{"label":"Άνω κάτω τελεία","default":"Άνω κάτω τελεία"},{"label":"Ερωτηματικό","default":"Ερωτηματικό"},{"label":"Συν","default":"Συν"},{"label":"Μείον","default":"Μείον"},{"label":"Αστερίσκος","default":"Αστερίσκος"},{"label":"Κάθετος","default":"Κάθετος"}]}]}'), JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)
