l":"Description du bouton \"Voir la réponse\" pour les outils d\'accessibilité","default":"Voir la réponse. L\'exercice s\'affichera avec la réponse correcte."},{"label":"Description du bouton \"Recommencer\" pour les outils d\'accessibilité","default":"Recommencer la tâche. Réinitialise toutes les réponses et redémarre l\'activité."},{"label":"Bouton de lecture","default":"Lecture"},{"label":"Bouton de lecture lente","default":"Lecture lente"},{"label":"Essais à gauche (texte à lire et texte à survoler)","description":"@number sera remplacé par le nombre actuel d\'essais restants.","default":"Nombre d\'essais restants : @number"},{"label":"Infini (texte à lire et texte à survoler)","default":"infinie"},{"label":"Entrez le champ de texte","default":"Entrez ce que vous avez entendu."},{"label":"Ton résultat","description":"@score will be replaced by the number of points. @total will be replaced by the maximum possible points.","default":"You got @score out of @total points"},{"label":"Solution","default":"Solution"},{"label":"Phrase","default":"Phrase"},{"label":"Item","default":"Item"},{"label":"Correct","default":"correct"},{"label":"Faux","default":"Faux"},{"label":"Petite erreur","default":"Petite erreur"},{"label":"Mot ou symbole manquant","default":"manquants"},{"label":"Mot ou symbole ajouté","default":"ajouté"},{"label":"Correct solution","default":"Should have been"},{"label":"Ou","default":"ou"},{"label":"Point","default":"point"},{"label":"Points","default":"points"},{"label":"Point","default":"point"},{"label":"Point d\'exclamation","default":"point d\'exclamation"},{"label":"Point d\'interrogation","default":"point d\'interrogation"},{"label":"Virgule","default":"virgule"},{"label":"Citation unique","default":"citation unique"},{"label":"Double citation","default":"double citation"},{"label":"Double point","default":"double point"},{"label":"Point-virgule","default":"point-virgule"},{"label":"Plus","default":"plus"},{"label":"Moins","default":"moins"},{"